<?php
namespace Tests\Unit; use PHPUnit\Framework\TestCase;
final class PublicDataPolicyContractTest extends TestCase { public function test_safe_defaults_and_attribution_hidden():void{$s=file_get_contents(dirname(__DIR__,2).'/src/Settings/PublicDataSettings.php');self::assertStringContainsString("'server.state'=>true",$s);self::assertStringContainsString("'resources.cpu_percent'=>false",$s);self::assertStringContainsString("'.attribution',false",$s);} public function test_server_override_precedes_global():void{$s=file_get_contents(dirname(__DIR__,2).'/src/Services/DefaultPublicDataPolicyResolver.php');self::assertStringContainsString("where('server_id',$server->id)",$s);self::assertStringContainsString("$o->visibility!=='inherit'",$s);} public function test_public_filter_hides_source_unless_enabled():void{$s=file_get_contents(dirname(__DIR__,2).'/src/Services/DefaultPublicDataPolicyResolver.php');self::assertStringContainsString("$source?($sourceLabel?:'Provider'):null",$s);} }
